function packGroups(tags: string[]): string[][] {
  const groups = new Map<string, string[]>();
  for (const t of tags) {
    const key = [...t].sort().join("");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(t);
  }
  return [...groups.values()];
}
